from openpi.training import config as _config
from openpi.policies import policy_config
import torch.nn as nn

train_config = _config.get_config('pi0_libero')
policy = policy_config.create_trained_policy(train_config, '/root/autodl-tmp/checkpoints/pi0_base', pytorch_device='cuda:0')

model = None
for attr in ('_model', 'model', '_network', 'network'):
    candidate = getattr(policy, attr, None)
    if isinstance(candidate, nn.Module):
        model = candidate
        print(f'Model found at policy.{attr}')
        break

if model is None:
    for attr in dir(policy):
        if not attr.startswith('__'):
            try:
                candidate = getattr(policy, attr)
                if isinstance(candidate, nn.Module):
                    model = candidate
                    print(f'Model found at policy.{attr}')
                    break
            except:
                pass

with open('/tmp/arch_output.txt', 'w') as f:
    for name, mod in model.named_modules():
        line = f'{name} -> {mod.__class__.__name__}'
        f.write(line + '\n')

    # Also print named parameters for attention layers
    f.write('\n=== PALIGEMMA LAYER 0 DETAILS ===\n')
    for name, param in model.named_parameters():
        if 'language_model.layers.0.' in name:
            f.write(f'{name} shape={list(param.shape)}\n')

    f.write('\n=== EXPERT LAYER 0 DETAILS ===\n')
    for name, param in model.named_parameters():
        if 'gemma_expert.model.layers.0.' in name:
            f.write(f'{name} shape={list(param.shape)}\n')

    # Total param count
    total = sum(p.numel() for p in model.parameters())
    f.write(f'\nTotal parameters: {total:,}\n')

print('Done. Output in /tmp/arch_output.txt')
